package com.example.homestay.ui.adapter;import android.content.res.ColorStateList;import android.graphics.Color;import android.view.*;import android.widget.TextView;import androidx.recyclerview.widget.RecyclerView;import com.example.homestay.R;import com.example.homestay.data.entity.*;import java.text.*;import java.util.*;
public class BookingAdapter extends RecyclerView.Adapter<BookingAdapter.Holder>{public interface Listener{void onBooking(BookingWithRoom value);}private final Listener click;private List<BookingWithRoom> items=Collections.emptyList();public BookingAdapter(Listener c){click=c;}public void submitList(List<BookingWithRoom> v){items=v;notifyDataSetChanged();}@Override public int getItemCount(){return items.size();}@Override public Holder onCreateViewHolder(ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_booking,p,false));}@Override public void onBindViewHolder(Holder h,int p){h.bind(items.get(p));}public class Holder extends RecyclerView.ViewHolder{final TextView id,status,roomName,dates,guests,price;Holder(View v){super(v);id=v.findViewById(R.id.tv_booking_id);status=v.findViewById(R.id.tv_status);roomName=v.findViewById(R.id.tv_room_name);dates=v.findViewById(R.id.tv_dates);guests=v.findViewById(R.id.tv_guests);price=v.findViewById(R.id.tv_total_price);}void bind(BookingWithRoom value){Booking b=value.getBooking();Room r=value.getRoom();String codeDate=new SimpleDateFormat("yyMMdd",Locale.getDefault()).format(new Date(b.getCreatedAt()));id.setText("#RG"+codeDate+String.format(Locale.ROOT,"%03d",b.getId()));status.setText(label(b.getStatus()));status.setBackgroundTintList(ColorStateList.valueOf(color(b.getStatus())));roomName.setText(r==null?"Phòng không tồn tại":r.getName());DateFormat df=new SimpleDateFormat("dd/MM",new Locale("vi","VN"));dates.setText("Nhận phòng: "+df.format(new Date(b.getCheckInDate()))+" · Trả phòng: "+df.format(new Date(b.getCheckOutDate())));guests.setText(b.getGuestCount()+" người lớn · 1 phòng");price.setText(NumberFormat.getNumberInstance(new Locale("vi","VN")).format((long)b.getTotalPrice())+" đ");itemView.setOnClickListener(v->click.onBooking(value));}}private static String label(String s){switch(s){case"pending":return"Chờ xác nhận";case"confirmed":return"Đã xác nhận";case"cancelled":return"Đã hủy";case"completed":return"Hoàn thành";default:return s;}}private static int color(String s){switch(s){case"pending":return Color.parseColor("#FF9800");case"confirmed":return Color.parseColor("#4CAF50");case"cancelled":return Color.parseColor("#F44336");case"completed":return Color.parseColor("#2196F3");default:return Color.GRAY;}}}
